8	 * @test @b openblas_dgemm
9	 * @parblock
10	 * Stress test for the vector FMA units using OpenBLAS's hand-written NEON
11	 * dgemm micro-kernel (TSV110). Literature identifies vector FMA as the #1
12	 * SDC source (SEVI ASPLOS'26: >92% of vector SDC incidents; Veritas HPCA'25:
13	 * vector units orders of magnitude above scalar). Each iteration copies the
14	 * inputs, computes C = A*B, and byte-compares against the golden product
15	 * from init (copy->compute->verify, the most frequent CORE179 trigger
16	 * structure). A third scheduling sample beside Eigen/ACL GEMM.
17	 * The matrix dimension is runtime-configurable via the test knob
18	 * "-O openblas_dgemm.mdim=N" (16..4096, default 256; the test-id
19	 * prefix is required — a bare "mdim=N" is silently ignored), sweeping
20	 * the working set across L1D (64KB) / L2 (512KB) / LLC / DRAM /
21	 * remote-NUMA on TSV110 (64: 32KB ... 1024: 8MB, 2048: 32MB, 4096:
22	 * 128MB per matrix) — the CORE179 probes showed the store->reload
23	 * cache-domain pattern is a triggering discriminator, so each size
24	 * class exercises different forwarding paths.
25	 * Two further runtime knobs (same test-id prefix rule) sweep orthogonal
26	 * axes of the kernel beside the working-set size: "-O
27	 * openblas_dgemm.transab=0..3" selects the TransA/TransB quadrant
28	 * (bit1=TransA, bit0=TransB: 0=NN default, 1=NT, 2=TN, 3=TT) —
29	 * transposed operands walk OpenBLAS's different internal packing
30	 * routines, i.e. different instruction-scheduling phases; and "-O
31	 * openblas_dgemm.beta_permille=0..1000000" sets beta=permille/1000
32	 * (default 0 = historical pure store into C; 1000 = beta 1.0), which
33	 * exercises the kernel's C read-modify-write path (C = alpha*op(A)*op(B)
34	 * + beta*C reads C instead of only writing it). With beta != 0 the
35	 * initial content of C participates in the result, so init seeds the
36	 * golden buffer and every run iteration seeds the thread-local C with
37	 * the same deterministic non-zero pattern (0.5*(i&63)/64.0, magnitude
38	 * <= ~0.49) before the cblas call; the golden finiteness sentinel below
39	 * still holds since |C| <= ~1.7e-2 + beta*0.5 (≈ 0.52 at the beta ≤ 1
40	 * operating point, ≈ 500 across the full beta_permille=1000000 range —
41	 * still hundreds of orders of magnitude below the 1e300 cutoff).
42	 * @endparblock
43	 */
44	
45	#include <sandstone.h>
46	
47	#include <cblas.h>
48	
49	#include <string.h>
50	#include <stdlib.h>
51	
52	namespace {
53	struct gemm_test_data {
54	    int mdim;             /* matrix dimension, from the -O openblas_dgemm.mdim=N knob */
55	    int transab;          /* TransA/TransB quadrant from -O openblas_dgemm.transab=0..3
56	                             (bit1=TransA, bit0=TransB: 0=NN 1=NT 2=TN 3=TT) */
57	    double beta;          /* beta = beta_permille/1000 from -O openblas_dgemm.beta_permille
58	                             (0.0 = historical pure store into C; != 0 exercises the
59	                             C read-modify-write path) */
60	    double *a;
61	    double *b;
62	    double *golden;      /* C = alpha*op(A)*op(B) + beta*C computed once in init; read-only after */
63	};
64	
65	/* Scratch buffers are per-thread: the framework runs one worker thread per
66	 * core and they all share test->data, so anything written during test_run
67	 * must be thread-local (a_copy/b_copy are the copy-in destinations, c is
68	 * the product destination; all three are written every iteration). They are
69	 * allocated lazily on first use and intentionally not freed in cleanup:
70	 * the worker threads are gone (or never existed) when the main thread runs
71	 * test_cleanup, and the whole forked child exits right after, so the OS
72	 * reclaims the storage. calloc zeroes c once so a skipped/short first
73	 * iteration can never compare garbage. */
74	static thread_local double *a_copy = nullptr;
75	static thread_local double *b_copy = nullptr;
76	static thread_local double *c = nullptr;
77	}
78	
79	#define CAST(_x) static_cast<struct gemm_test_data *>(_x)
80	
81	/* Map a random uint64 onto a finite, well-normalised double with a random
82	 * sign and a random 52-bit mantissa, magnitude in [1e-6, 2e-3]. See the
83	 * init comment for why the raw bit pattern cannot be used directly. */
84	static double random_bounded(void) {
85	    uint64_t r = random64();
86	    double frac = (double)(r >> 11) / 9007199254740992.0; /* [0, 1) */
87	    double sign = (r & 1) ? -1.0 : 1.0;
88	    return sign * (frac * 2.0e-3 + 1.0e-6);
89	}
90	
91	static int openblas_dgemm_init(struct test *test) {
92	    auto d = new(gemm_test_data);
93	    test->data = d;
94	    int64_t knob = get_testspecific_knob_value_int(test, "mdim", 256);
95	    if (knob < 16 || knob > 4096) {
96	        report_fail_msg("mdim knob out of range: %ld (valid 16..4096, default 256)", (long)knob);
97	    }
98	    d->mdim = (int)knob;
99	    int64_t transab = get_testspecific_knob_value_int(test, "transab", 0);
100	    if (transab < 0 || transab > 3) {
101	        report_fail_msg("transab knob out of range: %ld (valid 0..3: 0=NN 1=NT 2=TN 3=TT, default 0)", (long)transab);
102	    }
103	    int64_t beta_pm = get_testspecific_knob_value_int(test, "beta_permille", 0);
104	    if (beta_pm < 0 || beta_pm > 1000000) {
105	        report_fail_msg("beta_permille knob out of range: %ld (valid 0..1000000, default 0; beta=permille/1000)", (long)beta_pm);
106	    }
107	    d->transab = (int)transab;
108	    d->beta    = (double)beta_pm / 1000.0;
109	    size_t n2 = (size_t)d->mdim * (size_t)d->mdim;
110	    d->a      = (double *)malloc(n2 * sizeof(double));
111	    d->b      = (double *)malloc(n2 * sizeof(double));
112	    d->golden = (double *)malloc(n2 * sizeof(double));
113	    if (!d->a || !d->b || !d->golden) {
114	        report_fail_msg("OOM allocating %zu bytes", n2 * sizeof(double) * 3);
115	    }
116	    /* high-entropy random operands (framework RNG; libc rand is trapped).
117	     * A raw uint64 reinterpreted as double is a NaN/Inf exponent field about
118	     * a quarter of the time and NaN would poison the byte-exact comparison,
119	     * and plain division (x / 1.0e30) does not fix it (NaN propagates; the
120	     * remainder collapses toward subnormals). Instead the random bits are
121	     * folded into a bounded magnitude: the top 52 bits become the mantissa
122	     * fraction of a value in [~1e-6, ~2e-3] with a random sign. The full
123	     * 52-bit mantissa stays random (the SDC payload), while the K=mdim
124	     * dot products are bounded by K * (2e-3)^2 <= ~1.7e-2 (K <= 4096) —
125	     * forty orders of magnitude from overflow and far from subnormal
126	     * rounding. */
127	    for (size_t i = 0; i < n2; ++i) {
128	        d->a[i] = random_bounded();
129	        d->b[i] = random_bounded();
130	    }
131	    /* beta != 0 makes C's initial content part of the result
132	     * (C = alpha*op(A)*op(B) + beta*C), so seed the golden buffer with a
133	     * deterministic non-zero pattern before the reference call — test_run
134	     * seeds its thread-local C with the very same pattern before every
135	     * cblas call, keeping the byte-exact comparison valid (with the
136	     * default beta=0 the seed is fully overwritten, so the historical
137	     * behavior stays byte-identical). */
138	    for (size_t i = 0; i < n2; ++i)
139	        d->golden[i] = 0.5 * (double)(i & 63) / 64.0;
140	    cblas_dgemm(CblasRowMajor,
141	                (d->transab & 2) ? CblasTrans : CblasNoTrans,
142	                (d->transab & 1) ? CblasTrans : CblasNoTrans,
143	                d->mdim, d->mdim, d->mdim,
144	                1.0, d->a, d->mdim, d->b, d->mdim,
145	                d->beta, d->golden, d->mdim);
146	    /* reject a NaN/Inf-polluted golden at the source: if the random operands
147	     * produced a non-finite product the byte-exact comparison below would be
148	     * meaningless (NaN != NaN), so fail loudly instead of silently passing */
149	    for (size_t i = 0; i < n2; ++i) {
150	        double g = d->golden[i];
151	        if (g != g || g > 1.0e300 || g < -1.0e300) {
152	            report_fail_msg("golden product not finite at element %zu "
153	                            "(random operands need tighter scaling)", i);
154	        }
155	    }
156	    return EXIT_SUCCESS;
157	}
158	
159	static int openblas_dgemm_run(struct test *test, int cpu) {
160	    auto d = CAST(test->data);
161	    size_t bytes = (size_t)d->mdim * d->mdim * sizeof(double);
162	    size_t n2 = (size_t)d->mdim * d->mdim;
163	    long iter = 0;
164	    TEST_LOOP(test, 1) {
165	        /* lazily allocate this thread's scratch buffers */
166	        if (__builtin_expect(!a_copy || !b_copy || !c, 0)) {
167	            a_copy = (double *)malloc(bytes);
168	            b_copy = (double *)malloc(bytes);
169	            c      = (double *)calloc(1, bytes);
170	            if (!a_copy || !b_copy || !c)
171	                report_fail_msg("OOM allocating thread scratch (%zu bytes)", bytes * 3);
172	        }
173	
174	        /* copy-in (dirties cache lines, then reloads them in the kernel) */
175	        memcpy(a_copy, d->a, bytes);
176	        memcpy(b_copy, d->b, bytes);
177	
178	        /* re-seed C's initial content every iteration: with beta != 0 the
179	         * kernel reads C (read-modify-write), so each iteration must start
180	         * from the same deterministic pattern the golden product was seeded
181	         * with in init (recomputed inline — no extra shared array) */
182	        for (size_t i = 0; i < n2; ++i)
183	            c[i] = 0.5 * (double)(i & 63) / 64.0;
184	
185	        cblas_dgemm(CblasRowMajor,
186	                    (d->transab & 2) ? CblasTrans : CblasNoTrans,
187	                    (d->transab & 1) ? CblasTrans : CblasNoTrans,
188	                    d->mdim, d->mdim, d->mdim,
189	                    1.0, a_copy, d->mdim, b_copy, d->mdim,
190	                    d->beta, c, d->mdim);
191	
192	        ++iter;
193	        /* verify-out: byte-exact golden compare of inputs and product */
194	        if (memcmp(a_copy, d->a, bytes) != 0) {
195	            report_fail_msg("input A corrupted after GEMM (iteration %ld)", iter);
196	        }
197	        if (memcmp(b_copy, d->b, bytes) != 0) {
198	            report_fail_msg("input B corrupted after GEMM (iteration %ld)", iter);
199	        }
200	        memcmp_or_fail(c, d->golden, (size_t)d->mdim * d->mdim);
201	    }
202	    return EXIT_SUCCESS;
203	}
204	
205	static int openblas_dgemm_cleanup(struct test *test) {
206	    auto d = CAST(test->data);
207	    free(d->a); free(d->b); free(d->golden);
208	    delete d;
209	    return EXIT_SUCCESS;
210	}
211	
212	DECLARE_TEST(openblas_dgemm, "OpenBLAS DGEMM (NEON FMA micro-kernel, copy/compute/verify per iteration)")
213	  .groups = DECLARE_TEST_GROUPS(&group_math),
214	  .test_init = openblas_dgemm_init,
215	  .test_run = openblas_dgemm_run,
216	  .test_cleanup = openblas_dgemm_cleanup,
217	  .fracture_loop_count = 4,
218	  .quality_level = TEST_QUALITY_PROD,
219	END_DECLARE_TEST
