40	 * required — a bare "n=N" is silently ignored). The knob sweeps the
41	 * working set across L1D (64KB) / L2 (512KB) / LLC / DRAM on TSV110
42	 * (64: 32KB, 256: 512KB, 1024: 8MB, 2048: 32MB per matrix) at an O(n^3)
43	 * flop budget per iteration (2048^3 = 8.6e9 flops, matching the mdim 2048
44	 * GEMM class).
45	 * Note on the ROW_MAJOR layout: LAPACKE_dgesv internally transposes to
46	 * column-major, calls LAPACK_dgesv, and transposes back, allocating and
47	 * freeing its transposition work buffers with plain malloc/free inside
48	 * each call (lapacke_dgesv_work.c). Those buffers are call-local, and the
49	 * underlying OpenBLAS build is USE_LOCKING=1 (see tests/cpu/meson.build),
50	 * so concurrent calls from the framework's one-worker-per-core threads are
51	 * safe — the same reasoning that makes concurrent cblas_dgemm safe. The
52	 * buffers this test itself writes (ac/ipivc/xc) are thread-local.
53	 * @endparblock
54	 */
55	
56	#include <sandstone.h>
57	
58	#include <lapacke.h>
59	
60	#include <string.h>
61	#include <stdlib.h>
62	
63	namespace {
64	struct lu_test_data {
65	    int n;               /* matrix dimension, from the -O openblas_lu.n=N knob */
66	    double *a;           /* original matrix, n^2, read-only (input to the dgesv copy) */
67	    double *lu;          /* golden packed L\U factors (dgesv overwrites its A arg in-place) */
68	    int *ipiv;           /* golden pivot sequence, n ints */
69	    double *b;           /* right-hand side, n doubles (nrhs=1) */
70	    double *x;           /* golden solution (dgesv overwrites its B arg in-place) */
71	};
72	
73	/* Scratch buffers are per-thread: the framework runs one worker thread per
74	 * core and they all share test->data, so anything written during test_run
75	 * must be thread-local (ac is the copy-in matrix that dgesv factors in
76	 * place, ipivc receives the pivot sequence, xc is the right-hand side that
77	 * dgesv overwrites with the solution; all three are written every
