139	                // exists to catch) would otherwise go undetected in 3 of 4
140	                // lanes.
141	                float32x4_t va = vdupq_n_f32(a);
142	                float32x4_t vb = vdupq_n_f32(b);
143	                float32x4_t vc = vdupq_n_f32(c);
144	                float32x4_t vd = vfmaq_f32(vc, va, vb);
145	
146	                // Software reference: fmaf (single rounding, IEEE-754).
147	                sw_lane = fmaf(a, b, c);
148	                uint32_t sw_bits = bits_of(sw_lane);
149	
150	                // Byte-exact compare of every lane (1-bit ULP flip is caught).
151	                for (int lane = 0; lane < 4; ++lane) {
152	                    hw_lane = vgetq_lane_f32(vd, lane);
153	                    if (bits_of(hw_lane) != sw_bits) {
154	                        if (mismatches == 0) {
155	                            out_a = a; out_b = b; out_c = c;
156	                            out_hw = hw_lane; out_sw = sw_lane;
157	                        }
158	                        ++mismatches;
159	                    }

