1	/**
2	 * @file adcx_arm.cpp
3	 * @copyright SPDX-License-Identifier: Apache-2.0
4	 *
5	 * @test adcx_arm
6	 * @parblock
7	 * Testing ARM64 ADC/ADCS instructions via GMP library.
8	 * Golden result is precomputed in init using pure C++ (__int128) simulation.
9	 * Each run computes the result using GMP (which uses ADC/ADCS) and compares
10	 * against the precomputed golden. This pattern follows Intel OpenDCDiag's
11	 * Eigen-based test design.
12	 * @endparblock
13	 */
14	
15	#include <sandstone.h>
16	#include <gmp.h>
17	#include <cstdint>
18	#include <cstdio>
19	#include <cstring>
20	#include <random>
21	#include <vector>
22	#include <cinttypes>
23	#include <memory>
24	
25	// 测试配置：每个大整数由 4 个 64-bit 字组成（256 位）
26	static constexpr size_t NUM_WORDS = 4;
27	static constexpr size_t NUM_PAIRS = 1024;   // 每批测试的数据对数量
28	
29	// 测试数据封装（类似 EigenSparseTestData）
30	struct AdcxTestData {
31	    std::vector<uint64_t> a_words;      // 所有 a 的单词展开存储
32	    std::vector<uint64_t> b_words;      // 所有 b 的单词展开存储
33	    std::vector<uint64_t> golden_words; // 所有黄金结果的单词展开存储（包含进位）
34	    size_t num_pairs;
35	};
36	
37	// ============================================================================
38	// 黄金参考：软件模拟大整数加法（使用 __int128 模拟进位链）
39	// 返回结果 + 进位（扩展为 NUM_WORDS+1 个单词）
40	// ============================================================================
41	
42	static void software_add_words(const uint64_t *a_words, const uint64_t *b_words,
43	                               uint64_t *res_words, uint64_t &carry_out) {
44	    unsigned __int128 carry = 0;
45	    for (size_t i = 0; i < NUM_WORDS; ++i) {
46	        unsigned __int128 sum = (unsigned __int128)a_words[i] + b_words[i] + carry;
47	        res_words[i] = (uint64_t)sum;
48	        carry = sum >> 64;
49	    }
50	    res_words[NUM_WORDS] = (uint64_t)carry;  // 保存进位到扩展单词
51	    carry_out = (uint64_t)carry;
52	}
53	
54	// ============================================================================
55	// 初始化测试数据（生成随机 256-bit 大整数，并预计算黄金结果）
56	// ============================================================================
57	
58	static int adcx_arm_init(struct test *test) {
59	    try {
60	        auto data = std::make_unique<AdcxTestData>();
61	        data->num_pairs = NUM_PAIRS;
62	
63	        // 分配存储空间
64	        data->a_words.resize(NUM_PAIRS * NUM_WORDS);
65	        data->b_words.resize(NUM_PAIRS * NUM_WORDS);
66	        data->golden_words.resize(NUM_PAIRS * (NUM_WORDS + 1)); // 加一个进位位
67	
68	        // 生成随机数据（使用 GMP 生成大整数，然后导出为单词）
69	        gmp_randstate_t rng_state;
70	        gmp_randinit_default(rng_state);
71	        gmp_randseed_ui(rng_state, static_cast<unsigned long>(std::random_device{}()));
72	
73	        mpz_t a_tmp, b_tmp;
74	        mpz_init(a_tmp);
75	        mpz_init(b_tmp);
76	
77	        for (size_t i = 0; i < NUM_PAIRS; ++i) {
78	            // 生成随机 256 位数
79	            mpz_urandomb(a_tmp, rng_state, NUM_WORDS * 64);
80	            mpz_urandomb(b_tmp, rng_state, NUM_WORDS * 64);
81	
82	            // 导出 a 和 b 的单词
83	            size_t count_a, count_b;
84	            mpz_export(&data->a_words[i * NUM_WORDS], &count_a, -1, sizeof(uint64_t), 0, 0, a_tmp);
85	            mpz_export(&data->b_words[i * NUM_WORDS], &count_b, -1, sizeof(uint64_t), 0, 0, b_tmp);
86	
87	            // 如果导出的单词数少于 NUM_WORDS，高位补零（由于 vector 已初始化，零自动填充）
88	            // 如果多于 NUM_WORDS（不应发生），忽略高位（但理论上不会）
89	
90	            // 计算黄金结果（软件模拟）
91	            uint64_t sw_words[NUM_WORDS + 1];
92	            uint64_t carry;
93	            software_add_words(&data->a_words[i * NUM_WORDS],
94	                               &data->b_words[i * NUM_WORDS],
95	                               sw_words, carry);
96	            // 存储黄金结果
97	            memcpy(&data->golden_words[i * (NUM_WORDS + 1)], sw_words, (NUM_WORDS + 1) * sizeof(uint64_t));
98	        }
99	
100	        mpz_clear(a_tmp);
101	        mpz_clear(b_tmp);
102	        gmp_randclear(rng_state);
103	
104	        test->data = data.release();
105	        return EXIT_SUCCESS;
106	
107	    } catch (const std::exception &e) {
108	        log_skip(TestResourceIssueSkipCategory, "Exception during init: %s", e.what());
109	        return EXIT_SKIP;
110	    }
111	}
112	
113	// ============================================================================
114	// 运行测试（每个核心独立执行）
115	// ============================================================================
116	
117	static int adcx_arm_run(struct test *test, int cpu) {
118	    (void)cpu;
119	    auto *td = static_cast<AdcxTestData*>(test->data);
120	
121	    // 每个线程独立缓冲区，避免竞争
122	    uint64_t a_words[NUM_WORDS];
123	    uint64_t b_words[NUM_WORDS];
124	    uint64_t hw_words[NUM_WORDS + 1];
125	    mpz_t a_mpz, b_mpz, result_hw;
126	    mpz_init(a_mpz);
127	    mpz_init(b_mpz);
128	    mpz_init(result_hw);
129	
130	    // 用于一致性测试的 store/load 缓冲区
131	    uint64_t store_buf[NUM_WORDS + 1];
132	    uint64_t reload_buf[NUM_WORDS + 1];
133	
134	    do {
135	        // 遍历所有数据对
136	        for (size_t i = 0; i < td->num_pairs; ++i) {
137	            // 1. 从共享数据中加载输入
138	            memcpy(a_words, &td->a_words[i * NUM_WORDS], NUM_WORDS * sizeof(uint64_t));
139	            memcpy(b_words, &td->b_words[i * NUM_WORDS], NUM_WORDS * sizeof(uint64_t));
140	
141	            // 2. 构建 GMP 大整数（从单词导入）
142	            mpz_import(a_mpz, NUM_WORDS, -1, sizeof(uint64_t), 0, 0, a_words);
143	            mpz_import(b_mpz, NUM_WORDS, -1, sizeof(uint64_t), 0, 0, b_words);
144	
145	            // 3. 硬件执行：使用 GMP 的 mpz_add（内部会调用 ADC/ADCS）
146	            mpz_add(result_hw, a_mpz, b_mpz);
147	
148	            // 4. 将硬件结果导出为字数组（包括可能的进位）
149	            memset(hw_words, 0, (NUM_WORDS + 1) * sizeof(uint64_t));
150	            size_t count;
151	            mpz_export(hw_words, &count, -1, sizeof(uint64_t), 0, 0, result_hw);
152	            // 如果 count > NUM_WORDS，则高位有进位；否则高位为0
153	            if (count > NUM_WORDS) {
154	                // 进位已经包含在 hw_words[NUM_WORDS] 中（因为导出的总字数超过 NUM_WORDS）
155	                // 但我们的导出是从低到高，所以如果 count = NUM_WORDS+1，最后一个字就是进位
156	                // 但为了保险，我们仍然将未导出的高位清零（已提前 memset）
157	            }
158	
159	            // 5. 与预存黄金结果比较（包括进位）
160	            const uint64_t *golden = &td->golden_words[i * (NUM_WORDS + 1)];
161	            bool data_ok = true;
162	            for (size_t j = 0; j < NUM_WORDS + 1; ++j) {
163	                if (hw_words[j] != golden[j]) {
164	                    data_ok = false;
165	                    break;
166	                }
167	            }
168	
169	            // 6. 存储一致性测试（Store/Load）
170	            memcpy(store_buf, hw_words, (NUM_WORDS + 1) * sizeof(uint64_t));
171	            memcpy(reload_buf, store_buf, (NUM_WORDS + 1) * sizeof(uint64_t));
172	            bool consistent = true;
173	            for (size_t j = 0; j < NUM_WORDS + 1; ++j) {
174	                if (hw_words[j] != reload_buf[j]) {
175	                    consistent = false;
176	                    break;
177	                }
178	            }
179	
180	            bool passed = data_ok && consistent;
181	
182	            // 7. 输出结果（每次迭代都输出）
183	            const char *color = passed ? "\033[32m" : "\033[31m";
184	            const char *result_str = passed ? "PASS" : "FAIL";
185	
186	            fprintf(stderr,
187	                    "[adcx_arm] Iter %zu: a_high=0x%016" PRIx64 " b_high=0x%016" PRIx64 " "
188	                    "hw_high=0x%016" PRIx64 " golden_high=0x%016" PRIx64 " "
189	                    "carry hw=%" PRIu64 " golden=%" PRIu64 " consistent=%d → %s%s\033[0m\n",
190	                    i,
191	                    a_words[NUM_WORDS-1], b_words[NUM_WORDS-1],
192	                    hw_words[NUM_WORDS-1], golden[NUM_WORDS-1],
193	                    hw_words[NUM_WORDS], golden[NUM_WORDS],
194	                    consistent,
195	                    color, result_str);
196	
197	            if (!passed) {
198	                report_fail_msg("adcx_arm: mismatch at pair %zu", i);
199	                mpz_clear(a_mpz);
200	                mpz_clear(b_mpz);
201	                mpz_clear(result_hw);
202	                return EXIT_FAILURE;
203	            }
204	        }
205	
206	    } while (test_time_condition(test));
207	
208	    mpz_clear(a_mpz);
209	    mpz_clear(b_mpz);
210	    mpz_clear(result_hw);
211	    return EXIT_SUCCESS;
212	}
213	
214	// ============================================================================
215	// 清理资源
216	// ============================================================================
217	
218	static int adcx_arm_finish(struct test *test) {
219	    delete static_cast<AdcxTestData*>(test->data);
220	    return EXIT_SUCCESS;
221	}
222	
223	// ============================================================================
224	// 测试注册
225	// ============================================================================
226	
227	DECLARE_TEST(adcx_arm, "Testing ARM64 ADC/ADCS via GMP with precomputed golden (Eigen-like pattern)")
228	    .groups = DECLARE_TEST_GROUPS(&group_math),
229	    .test_init = adcx_arm_init,
230	    .test_run = adcx_arm_run,
231	    .test_cleanup = adcx_arm_finish,
232	    .fracture_loop_count = 4,
233	    .quality_level = TEST_QUALITY_PROD
234	END_DECLARE_TEST
