36	
37	// 辅助：GMP -> uint64_t 数组（小端序），只取低 low_words 个字
38	static void mpz_to_words_trunc(uint64_t *words, const mpz_t src, int num_words) {
39	    // 截断 src 到 num_words * 64 位
40	    mpz_t tmp;
41	    mpz_init(tmp);
42	    mpz_mod_2exp(tmp, src, num_words * 64);
43	    memset(words, 0, num_words * sizeof(uint64_t));
44	    mpz_export(words, nullptr, -1, sizeof(uint64_t), 0, 0, tmp);
45	    mpz_clear(tmp);
46	}
47	
48	// 辅助：uint64_t 数组 -> GMP
49	static void words_to_mpz(mpz_t dst, const uint64_t *words, int num_words) {
50	    mpz_import(dst, num_words, -1, sizeof(uint64_t), 0, 0, words);
51	}
52	
53	// 初始化：生成固定随机输入，预计算黄金结果。所有线程共享同一份只读数据。
54	static int bigint_mulx_arm_init(struct test *test) {
55	    auto *data = new TestData;
56	    if (!data) return EXIT_FAILURE;
57	
58	    data->a_words.resize(NUM_WORDS);
59	    data->b_words.resize(NUM_WORDS);
60	    data->golden_product.resize(NUM_WORDS);
61	
62	    std::mt19937_64 rng(FIXED_SEED);
63	    std::uniform_int_distribution<uint64_t> dist(0, UINT64_MAX);
64	
65	    for (int i = 0; i < NUM_WORDS; ++i) {
66	        data->a_words[i] = dist(rng);
67	        data->b_words[i] = dist(rng);
68	    }
69	
70	    // 使用 GMP 计算精确乘积
71	    mpz_t a, b, product;
72	    mpz_init(a);
73	    mpz_init(b);
74	    mpz_init(product);
75	
76	    words_to_mpz(a, data->a_words.data(), NUM_WORDS);
77	    words_to_mpz(b, data->b_words.data(), NUM_WORDS);
78	    mpz_mul(product, a, b);
79	
80	    // 提取乘积的低 NUM_WORDS 个字（512 位）
81	    mpz_to_words_trunc(data->golden_product.data(), product, NUM_WORDS);
82	
83	    mpz_clear(a);
84	    mpz_clear(b);
85	    mpz_clear(product);
86	
87	    test->data = data;
88	    return EXIT_SUCCESS;
89	}
90	
91	// 运行测试：每次迭代计算并比较，使用线程局部缓冲
92	static int bigint_mulx_arm_run(struct test *test, int cpu) {
93	    (void)cpu;
94	    auto *data = static_cast<TestData*>(test->data);
95	    if (!data) return EXIT_FAILURE;
96	
97	    const uint64_t *a = data->a_words.data();
98	    const uint64_t *b = data->b_words.data();
99	
100	    mpz_t a_mpz, b_mpz, product;
101	    mpz_init(a_mpz);
102	    mpz_init(b_mpz);
103	    mpz_init(product);
104	
105	    do {
106	        // 使用 GMP 重新计算乘积
107	        words_to_mpz(a_mpz, a, NUM_WORDS);
108	        words_to_mpz(b_mpz, b, NUM_WORDS);
109	        mpz_mul(product, a_mpz, b_mpz);
110	
111	        uint64_t result[NUM_WORDS];
112	        mpz_to_words_trunc(result, product, NUM_WORDS);
113	
114	        // 与黄金结果比较
115	        bool data_ok = true;
116	        int mismatch_word = 0;
117	        for (int i = 0; i < NUM_WORDS; ++i) {
118	            if (result[i] != data->golden_product[i]) {
119	                data_ok = false;
120	                mismatch_word = i;
121	                break;
122	            }
123	        }
124	
125	        // 存储一致性测试
126	        uint64_t store_buf[NUM_WORDS];
127	        memcpy(store_buf, result, sizeof(store_buf));
128	        uint64_t reload_buf[NUM_WORDS];
129	        memcpy(reload_buf, store_buf, sizeof(store_buf));
130	        bool consistent = (memcmp(reload_buf, result, sizeof(result)) == 0);
131	
132	        bool passed = data_ok && consistent;
133	
134	        if (!passed) {
135	            // Fail 详查：把本次输入(a,b)与输出(result,golden)落进 yaml 的 data: 字段，
136	            // 再用 report_fail_msg 记录失败位置（框架自动标 thread failed）。
137	            // report_fail_msg 是 noreturn，调用前先释放 GMP 资源。
