8	 * @test @b gmp_bignum
9	 * @parblock
10	 * Stress the integer execution units by repeatedly multiplying
11	 * large multi-precision integers via the third-party GMP library.
12	 * Two random big integers (4096-bit each) are generated at init by
13	 * importing a buffer of random bytes and their product is computed
14	 * as a golden result.  During the run the same multiplication is
15	 * repeated and every limb is compared against the golden.  Any
16	 * mismatch indicates a silent data corruption in the ALU / multiply
17	 * pipeline of the core running the thread.
18	 * @endparblock
19	 */
20	
21	#include <sandstone.h>
22	#include <gmp.h>
23	
24	#define GMP_BITS 4096
25	#define GMP_BYTELEN ((GMP_BITS) / 8)        /* 512 bytes */
26	#define GMP_BYTELENLIMBS(l) ((l) * sizeof(mp_limb_t))
27	
28	namespace {
29	struct gmp_data {
30	    mpz_t a;
31	    mpz_t b;
32	    mpz_t golden;           /* a * b, computed once at init */
33	    mp_limb_t *golden_buf;  /* golden limbs snapshot for memcmp */
34	    size_t golden_size;
35	};
36	}
37	
38	#define CAST(_x) static_cast<struct gmp_data *>(_x)
39	
40	/* fill a buffer with random bytes derived from random32() */
41	static void fill_random_bytes(uint8_t *buf, size_t n)
42	{
43	    for (size_t i = 0; i < n; i += 4) {
44	        uint32_t r = random32();
45	        for (int j = 0; j < 4 && (i + j) < n; ++j)
46	            buf[i + j] = (uint8_t)(r >> (8 * j));
47	    }
48	}
49	
50	static int gmp_bignum_init(struct test *test)
51	{
52	    gmp_data *data = new gmp_data;
53	    mpz_init(data->a);
54	    mpz_init(data->b);
55	    mpz_init(data->golden);
56	    data->golden_buf = nullptr;
57	    data->golden_size = 0;
58	
59	    uint8_t buf[GMP_BYTELEN];
60	    fill_random_bytes(buf, GMP_BYTELEN);
61	    /* order=1 (most significant word first), size=1, endian=little, nails=0 */
62	    mpz_import(data->a, GMP_BYTELEN, 1, 1, 1, 0, buf);
63	    fill_random_bytes(buf, GMP_BYTELEN);
64	    mpz_import(data->b, GMP_BYTELEN, 1, 1, 1, 0, buf);
65	
66	    mpz_mul(data->golden, data->a, data->b);
67	    data->golden_size = mpz_size(data->golden);
68	    data->golden_buf = (mp_limb_t *)aligned_alloc_safe(64,
69	                          GMP_BYTELENLIMBS(data->golden_size));
70	    for (size_t i = 0; i < data->golden_size; ++i)
71	        data->golden_buf[i] = mpz_getlimbn(data->golden, i);
72	
73	    test->data = data;
74	    return EXIT_SUCCESS;
75	}
76	
77	static int gmp_bignum_run(struct test *test, int cpu)
78	{
79	    auto data = CAST(test->data);
80	    mpz_t result;
81	    mpz_init(result);
82	
83	    do {
84	        mpz_mul(result, data->a, data->b);
85	        size_t rsize = mpz_size(result);
86	        if (rsize != data->golden_size) {
87	            mpz_clear(result);
88	            report_fail_msg("GMP mul produced unexpected size %zu vs %zu",
89	                            rsize, data->golden_size);
90	        }
91	        for (size_t i = 0; i < rsize; ++i) {
92	            mp_limb_t got = mpz_getlimbn(result, i);
93	            if (got != data->golden_buf[i]) {
94	                mpz_clear(result);
95	                report_fail_msg("GMP big-mul limb %zu mismatch: 0x%llx vs 0x%llx",
96	                                i, (unsigned long long)got,
97	                                (unsigned long long)data->golden_buf[i]);
98	            }
99	        }
100	    } while (test_time_condition(test));
101	
102	    mpz_clear(result);
103	    return EXIT_SUCCESS;
104	}
105	
106	static int gmp_bignum_cleanup(struct test *test)
107	{
108	    gmp_data *data = CAST(test->data);
109	    mpz_clear(data->a);
110	    mpz_clear(data->b);
111	    mpz_clear(data->golden);
112	    free(data->golden_buf);
113	    delete data;
114	    return EXIT_SUCCESS;
115	}
116	
117	DECLARE_TEST(gmp_bignum, "GMP large integer multiplication (4096-bit) vs golden result")
118	  .groups = DECLARE_TEST_GROUPS(&group_math),
119	  .test_init = gmp_bignum_init,
120	  .test_run = gmp_bignum_run,
121	  .test_cleanup = gmp_bignum_cleanup,
122	  .quality_level = TEST_QUALITY_PROD,
123	END_DECLARE_TEST
