1	/**
2	 * @file
3	 *
4	 * @copyright
5	 * Copyright 2022 Intel Corporation.
6	 * SPDX-License-Identifier: Apache-2.0
7	 *
8	 * @test @b acl_gemm
9	 * @parblock
10	 * Stress the floating-point multiply-accumulate path using the Arm
11	 * Compute Library's NEON GEMM (NEGEMM).  Two random F32 matrices
12	 * (M=N=K=64) are generated at init and the golden product is
13	 * computed with a naive triple loop.  The ACL scheduler is pinned to
14	 * a single thread so the ACL op runs inline on the sandstone worker
15	 * thread itself.  During the run the GEMM is re-executed and the
16	 * output is compared byte-by-byte against the golden.  A mismatch
17	 * indicates a silent corruption in the FPU / FMA / NEON pipeline.
18	 * @endparblock
19	 */
20	
21	#include <sandstone.h>
22	
23	#include <cmath>
24	
25	#include "arm_compute/core/Types.h"
26	#include "arm_compute/runtime/NEON/NEFunctions.h"
27	#include "arm_compute/runtime/NEON/NEScheduler.h"
28	#include "arm_compute/runtime/Tensor.h"
29	
30	#define ACL_DIM 64
31	
32	namespace {
33	struct acl_gemm_data {
34	    arm_compute::Tensor a;
35	    arm_compute::Tensor b;
36	    arm_compute::Tensor d;          /* ACL output */
37	    float *golden;                 /* naive C = alpha*A*B, beta=0 (long double accum) */
38	    arm_compute::NEGEMM *gemm;      /* op handle, configured once */
39	    /* per-thread scratch imported into the ACL tensors via import_memory()
40	     * so ACL owns no heap that would have to survive sandstone's
41	     * fork-per-iteration fracturing (same fork-safety pattern as
42	     * fisttp_arm.cpp). 128-byte aligned like the fisttp_arm buffers. */
43	    alignas(128) float a_buf[ACL_DIM * ACL_DIM];
44	    alignas(128) float b_buf[ACL_DIM * ACL_DIM];
45	    alignas(128) float d_buf[ACL_DIM * ACL_DIM];
46	};
47	}
48	
49	#define CAST(_x) static_cast<struct acl_gemm_data *>(_x)
50	
51	/* naive reference GEMM: d[i*ACL_DIM+j] = sum_k a[i,k]*b[k,j].
52	 * long double accumulation: an INDEPENDENT high-precision reference for the
53	 * ACL NEON kernel result (which accumulates in float in a different order),
54	 * so the tolerance below can be tight (~1e-5 relative = ~10^3 ulp at float
55	 * width) while remaining immune to reordering rounding. */
56	static void naive_gemm(const float *A, const float *B, float *C)
57	{
58	    for (int i = 0; i < ACL_DIM; ++i)
59	        for (int j = 0; j < ACL_DIM; ++j) {
60	            long double acc = 0.0L;
61	            for (int k = 0; k < ACL_DIM; ++k)
62	                acc += (long double)A[i * ACL_DIM + k] * (long double)B[k * ACL_DIM + j];
63	            C[i * ACL_DIM + j] = (float)acc;
64	        }
65	}
66	
67	static int acl_gemm_init(struct test *test)
68	{
69	    acl_gemm_data *data = new acl_gemm_data;
70	    data->gemm = nullptr;
71	    data->golden = nullptr;
72	    /* THE FIX: the historical SIGSEGV was never "fork-per-iteration" — this
73	     * assignment was simply missing, so test_run/test_cleanup dereferenced a
74	     * NULL/garbage test->data (struct offset 0x500 region). fisttp_arm.cpp:114
75	     * has it; this test never did. */
76	    test->data = data;
77	
78	    /* force ACL to run its kernels inline on this thread (single thread)
79	     * so we do not nest a thread pool inside the sandstone worker. */
80	    arm_compute::NEScheduler::get().set_num_threads(1);
81	
82	    using namespace arm_compute;
83	    arm_compute::TensorInfo info(arm_compute::TensorShape(ACL_DIM, ACL_DIM), 1, arm_compute::DataType::F32);
84	    info.set_data_layout(arm_compute::DataLayout::NHWC);
85	    data->a.allocator()->init(info);
86	    data->b.allocator()->init(info);
87	    data->d.allocator()->init(info);
88	    /* import_memory instead of allocate(): the tensors borrow the
89	     * per-thread aligned buffers above; ACL allocates/owns nothing that
90	     * would need to survive a fork (fork-safe, fisttp_arm.cpp pattern). */
91	    data->a.allocator()->import_memory(data->a_buf);
92	    data->b.allocator()->import_memory(data->b_buf);
93	    data->d.allocator()->import_memory(data->d_buf);
94	
95	    /* fill A, B with random floats in [-1, 1) */
96	    float *A = data->a_buf;
97	    float *B = data->b_buf;
98	    for (int i = 0; i < ACL_DIM * ACL_DIM; ++i) {
99	        A[i] = (float)((int32_t)random32()) / (float)(1u << 30);
100	        B[i] = (float)((int32_t)random32()) / (float)(1u << 30);
101	    }
102	
103	    /* golden = 1.0 * A * B + 0.0 * C (independent long-double reference) */
104	    data->golden = (float *)aligned_alloc_safe(64, ACL_DIM * ACL_DIM * sizeof(float));
105	    naive_gemm(A, B, data->golden);
106	
107	    data->gemm = new arm_compute::NEGEMM;
108	    data->gemm->configure(&data->a, &data->b, nullptr, &data->d,
109	                          1.0f, 0.0f, arm_compute::GEMMInfo{});
110	    return EXIT_SUCCESS;
111	}
112	
113	static int acl_gemm_run(struct test *test, int cpu)
114	{
115	    auto data = CAST(test->data);
116	    /* ACL NEGEMM shares a process-global scheduler; only one worker
117	     * thread may execute the op at a time to avoid concurrent
118	     * scheduler state corruption. Other threads simply idle. */
119	    if (cpu != 0)
120	        return EXIT_SUCCESS;
121	    do {
122	        data->gemm->prepare();
123	        data->gemm->run();
124	        float *out = data->d_buf;
125	        /* compare against the independent long-double naive golden.
126	         * The ACL NEON kernel accumulates in float in a different
127	         * order than the reference, so a tight RELATIVE tolerance
128	         * (~1e-5, i.e. ~10^3 float ulp) absorbs the healthy
129	         * reordering rounding while any real SDC — a flipped FMA
130	         * operand bit, a wrong kernel constant — lands orders of
131	         * magnitude outside it. Transient 1-ulp errors are this
132	         * test's bread and butter only at the byte level; here the
133	         * target is gross deterministic kernel corruption, and the
134	         * 1e-3f absolute floor of the old comparison is gone. */
135	        for (int i = 0; i < ACL_DIM * ACL_DIM; ++i) {
136	            float diff = out[i] - data->golden[i];
137	            if (diff < 0) diff = -diff;
138	            /* Tolerance calibration (measured, two rounds): the ACL NEON kernel
139	             * accumulates K=64 float products in its own tiling order while the
140	             * golden is a long-double reference. A pure relative tolerance is
141	             * wrong for this workload: near-cancellation outputs (|golden| as
142	             * small as ~9e-4 from |a|,|b| <= 1 operands) carry an absolute
143	             * rounding gap of ~4e-7 — a ~4e-4 RELATIVE gap that no sane
144	             * relative tolerance can absorb. The correct bound is absolute and
145	             * scales with the operand magnitude, not the output: K*eps*max|a*b|
146	             * = 64 * 1.2e-7 * 1 ~ 7.7e-6. Use 1e-4f absolute: ~13x headroom
147	             * over that worst case (no false positives on healthy silicon,
148	             * verified) while a real SDC — flipped FMA operand bit, wrong
149	             * kernel constant — produces O(1)-magnitude errors, 4 orders above
150	             * it. Still 10x tighter than the old 1e-3f absolute floor, which
151	             * additionally had no cancellation story at all. */
152	            float tol = 1e-4f;
153	            if (diff > tol) {
154	                report_fail_msg("ACL GEMM mismatch at (%d,%d): %g vs golden %g "
155	                                "(diff %g)", i / ACL_DIM, i % ACL_DIM,
156	                                (double)out[i], (double)data->golden[i],
157	                                (double)diff);
158	            }
159	        }
160	    } while (test_time_condition(test));
161	    return EXIT_SUCCESS;
162	}
163	
164	static int acl_gemm_cleanup(struct test *test)
165	{
166	    acl_gemm_data *data = CAST(test->data);
167	    delete data->gemm;
168	    free(data->golden);
169	    delete data;
170	    return EXIT_SUCCESS;
171	}
172	
173	DECLARE_TEST(acl_gemm, "Arm Compute Library NEON GEMM (F32 64x64) vs naive golden")
174	  .groups = DECLARE_TEST_GROUPS(&group_math),
175	  .test_init = acl_gemm_init,
176	  .test_run = acl_gemm_run,
177	  .test_cleanup = acl_gemm_cleanup,
178	  .quality_level = TEST_QUALITY_PROD,
179	END_DECLARE_TEST
180

