1	/**
2	 * @file operand_space_arm.cpp
3	 * @copyright SPDX-License-Identifier: Apache-2.0
4	 *
5	 * @test operand_space_arm
6	 * @parblock
7	 * Operand-space SDC stressor: feeds the ARM64 adder / carry-chain / multiplier
8	 * a *deterministic high-Hamming-distance operand table* that forces maximum
9	 * per-cycle gate toggling (0x0000... <-> 0xFFFF... alternating, 0xAAAA... <->
10	 * 0x5555..., walking-one/zero), instead of uniform-random inputs.
11	 *
12	 * Rationale (SDC coverage gap, "版图一.1 操作数空间"): every existing integer
13	 * test in this suite feeds the ALU uniform-random 64-bit operands
14	 * (random32()/mpz_urandomb/mt19937), which average ~16 bits of Hamming distance
15	 * between successive values and rarely hit the worst-case carry-propagation /
16	 * prefix-adder / multiplier partial-product paths. Alternating between bitwise
17	 * complements (Hamming distance 64) every cycle forces every gate in the
18	 * carry/sum network to toggle 0->1 and 1->0, which is the pattern most likely
19	 * to excite delay faults and produce silent data corruption.
20	 *
21	 * The hardware path runs the big-integer add through GMP (mp_add, which lowers
22	 * to ADCS), and a 64x64->128 UMULL via mpz_mul; the golden is precomputed in
23	 * test_init using pure __int128 software simulation. Each run compares the
24	 * hardware result against the golden with a per-word byte-exact check, a
25	 * real store-to-load-forwarding probe (inline-asm str then ldr to the same
26	 * buffer — the store buffer satisfying the subsequent load, a corruption-prone
27	 * datapath), and a full 128-bit multiply check (both UMULL-low and UMULH-high
28	 * halves, the high half being a timing-critical path). No per-iteration
29	 * logging (avoids the timing-perturbation hazard seen in adcx_arm.cpp:186 /
30	 * adcxlong.cpp:162).
31	 *
32	 * ARM64-native (GMP is consumed on aarch64); the whole subdir is entered only
33	 * under the aarch64 guard in tests/cpu/meson.build, so x86-64 is untouched.
34	 * @endparblock
35	 */
36	
37	#include <sandstone.h>
38	#include <gmp.h>
39	#include <cstdint>
40	#include <cinttypes>
41	#include <cstring>
42	#include <memory>
43	
44	// 256-bit big integer = 4 x 64-bit words.
45	static constexpr size_t NUM_WORDS = 4;
46	// Number of (a, b) operand pairs derived from the high-Hamming table.
47	// Set to the table size so one pass cycles through every entry (the high-bit
48	// walking-one values at the tail of the table are otherwise unreached in a
49	// NUM_PAIRS < table-size cycle).
50	static constexpr size_t NUM_PAIRS = 80;
51	
52	// ============================================================================
53	// High-Hamming-distance operand table.
54	//
55	// Each entry is a 64-bit word. Successive entries are chosen to maximise the
56	// number of bits that change between one operand and the next, forcing maximum
57	// gate toggling in the carry/sum/partial-product networks. A full big integer
58	// is built by replicating a chosen base word across all NUM_WORDS lanes (so a
59	// 0xFFFF...F word makes a 256-bit all-ones value), which keeps the carry chain
60	// fully exercised across all lanes.
61	// ============================================================================
62	static const uint64_t HAMMING_TABLE[] = {
63	    0x0000000000000000ULL,
64	    0xFFFFFFFFFFFFFFFFULL,   // Hamming distance 64 vs previous (max toggle)
65	    0xAAAAAAAAAAAAAAAAULL,   // even bits
66	    0x5555555555555555ULL,    // odd bits  (distance 64 vs previous)
67	    0x0F0F0F0F0F0F0F0FULL,
68	    0xF0F0F0F0F0F0F0F0ULL,   // distance 64 vs previous
69	    0x00FF00FF00FF00FFULL,
70	    0xFF00FF00FF00FF00ULL,    // distance 64 vs previous
71	    0x0000FFFF0000FFFFULL,
72	    0xFFFF0000FFFF0000ULL,    // distance 64 vs previous
73	    0x00000000FFFFFFFFULL,
74	    0xFFFFFFFF00000000ULL,    // distance 64 vs previous
75	    0x123456789ABCDEF0ULL,    // structured mixed pattern
76	    0xEDCBA9876543210ULL,     // bitwise complement of above (distance 64)
77	    0x0123456789ABCDEFULL,
78	    0xFEDCBA9876543210ULL,    // complement (distance 64)
79	    // walking-one: a single bit set, successive entries shift the bit, so the
80	    // carry chain sees a single hot bit walking through all 64 positions.
81	    0x0000000000000001ULL,
82	    0x0000000000000002ULL,
83	    0x0000000000000004ULL,
84	    0x0000000000000008ULL,
85	    0x0000000000000010ULL,
86	    0x0000000000000020ULL,
87	    0x0000000000000040ULL,
88	    0x0000000000000080ULL,
89	    0x0000000000000100ULL,
90	    0x0000000000000200ULL,
91	    0x0000000000000400ULL,
92	    0x0000000000000800ULL,
93	    0x0000000000001000ULL,
94	    0x0000000000002000ULL,
95	    0x0000000000004000ULL,
96	    0x0000000000008000ULL,
97	    0x0000000000010000ULL,
98	    0x0000000000020000ULL,
99	    0x0000000000040000ULL,
100	    0x0000000000080000ULL,
101	    0x0000000000100000ULL,
102	    0x0000000000200000ULL,
103	    0x0000000000400000ULL,
104	    0x0000000000800000ULL,
105	    0x0000000001000000ULL,
106	    0x0000000002000000ULL,
107	    0x0000000004000000ULL,
108	    0x0000000008000000ULL,
109	    0x0000000010000000ULL,
110	    0x0000000020000000ULL,
111	    0x0000000040000000ULL,
112	    0x0000000080000000ULL,
113	    0x0000000100000000ULL,
114	    0x0000000200000000ULL,
115	    0x0000000400000000ULL,
116	    0x0000000800000000ULL,
117	    0x0000001000000000ULL,
118	    0x0000002000000000ULL,
119	    0x0000004000000000ULL,
120	    0x0000008000000000ULL,
121	    0x0000010000000000ULL,
122	    0x0000020000000000ULL,
123	    0x0000040000000000ULL,
124	    0x0000080000000000ULL,
125	    0x0000100000000000ULL,
126	    0x0000200000000000ULL,
127	    0x0000400000000000ULL,
128	    0x0000800000000000ULL,
129	    0x0001000000000000ULL,
130	    0x0002000000000000ULL,
131	    0x0004000000000000ULL,
132	    0x0008000000000000ULL,
133	    0x0010000000000000ULL,
134	    0x0020000000000000ULL,
135	    0x0040000000000000ULL,
136	    0x0080000000000000ULL,
137	    0x0100000000000000ULL,
138	    0x0200000000000000ULL,
139	    0x0400000000000000ULL,
140	    0x0800000000000000ULL,
141	    0x1000000000000000ULL,
142	    0x2000000000000000ULL,
143	    0x4000000000000000ULL,
144	    0x8000000000000000ULL,
145	};
146	static constexpr size_t HAMMING_TABLE_SIZE = sizeof(HAMMING_TABLE) / sizeof(HAMMING_TABLE[0]);
147	
148	struct OperandSpaceData {
149	    std::vector<uint64_t> a_words;        // NUM_PAIRS * NUM_WORDS
150	    std::vector<uint64_t> b_words;       // NUM_PAIRS * NUM_WORDS
151	    std::vector<uint64_t> golden_add;     // NUM_PAIRS * (NUM_WORDS + 1)  (with carry-out)
152	    std::vector<uint64_t> golden_mul_lo;  // NUM_PAIRS (low 64 bits of a[0]*b[0])
153	    std::vector<uint64_t> golden_mul_hi;  // NUM_PAIRS (high 64 bits of a[0]*b[0]) — UMULH path
154	    size_t num_pairs;
155	};
156	
157	// ----------------------------------------------------------------------------
158	// Software reference: 256-bit big-integer add with carry propagation, using
159	// __int128 to model the ADCS carry chain. Emits NUM_WORDS + 1 words (the extra
160	// word holds carry-out).
161	// ----------------------------------------------------------------------------
162	static void software_add_words(const uint64_t *a, const uint64_t *b,
163	                               uint64_t *res)
164	{
165	    unsigned __int128 carry = 0;
166	    for (size_t i = 0; i < NUM_WORDS; ++i) {
167	        unsigned __int128 sum = (unsigned __int128)a[i] + b[i] + carry;
168	        res[i] = (uint64_t)sum;
169	        carry = sum >> 64;
170	    }
171	    res[NUM_WORDS] = (uint64_t)carry;
172	}
173	
174	// Build a 256-bit operand by replicating base_word across all NUM_WORDS lanes.
175	// (Replication keeps every lane of the carry chain fully toggling when the
176	// base word flips, rather than leaving high lanes quiescent.)
177	static inline void fill_operand(uint64_t *dst, uint64_t base_word)
178	{
179	    for (size_t i = 0; i < NUM_WORDS; ++i)
180	        dst[i] = base_word;
181	}
182	
183	// ----------------------------------------------------------------------------
184	// Store-to-load-forwarding probe. The previous version did a software
185	// memcpy(store_buf, hw) then memcpy(reload_buf, store_buf) and compared — that
186	// is a memory-to-memory copy through the compiler/regalloc, NOT a hardware
187	// store->load forward; the store-load forwarding datapath (the store buffer
188	// satisfying a subsequent load to the same address before it hits L1) was never
189	// actually exercised. Here we issue a real store then a real load to the same
190	// address via inline asm with a "memory" clobber, defeating the optimizer so
191	// the store and load are emitted as separate str/ldr micro-ops hitting the
192	// store buffer. On non-aarch64 we fall back to a plain store+load (still a real
193	// memory round-trip, unlike the memcpy version).
194	// ----------------------------------------------------------------------------
195	#if defined(__aarch64__)
196	static inline uint64_t slf_probe(const uint64_t *src, uint64_t *buf, size_t n)
197	{
198	    // 1. Copy src -> buf via stores (str).
199	    for (size_t i = 0; i < n; ++i) {
200	        __asm__ volatile("str %1, [%0, %2]"
201	                         : : "r"(buf), "r"(src[i]), "r"(i * sizeof(uint64_t))
202	                         : "memory");
203	    }
204	    // 2. Sum-reload every element via loads (ldr) from buf — each load is
205	    //    satisfied by the just-written store buffer entry (store-to-load
206	    //    forwarding). A fault in the forwarding path corrupts the sum.
207	    uint64_t acc = 0;
208	    for (size_t i = 0; i < n; ++i) {
209	        uint64_t v;
210	        __asm__ volatile("ldr %0, [%1, %2]"
211	                         : "=r"(v)
212	                         : "r"(buf), "r"(i * sizeof(uint64_t))
213	                         : "memory");
214	        acc += v;
215	    }
216	    return acc;
217	}
218	#else
219	static inline uint64_t slf_probe(const uint64_t *src, uint64_t *buf, size_t n)
220	{
221	    for (size_t i = 0; i < n; ++i)
222	        buf[i] = src[i];
223	    uint64_t acc = 0;
224	    for (size_t i = 0; i < n; ++i)
225	        acc += buf[i];
226	    return acc;
227	}
228	#endif
229	
230	static int operand_space_arm_init(struct test *test)
231	{
232	    try {
233	        auto data = std::make_unique<OperandSpaceData>();
234	        data->num_pairs = NUM_PAIRS;
235	        data->a_words.resize(NUM_PAIRS * NUM_WORDS);
236	        data->b_words.resize(NUM_PAIRS * NUM_WORDS);
237	        data->golden_add.resize(NUM_PAIRS * (NUM_WORDS + 1));
238	        data->golden_mul_lo.resize(NUM_PAIRS);
239	        data->golden_mul_hi.resize(NUM_PAIRS);
240	
241	        // Generate operand pairs by cycling through the high-Hamming table.
242	        // Successive pairs pick complementary table entries (i and i+1 mod N)
243	        // so that consecutive iterations see a full bitwise complement and the
244	        // carry chain toggles maximally.
245	        for (size_t i = 0; i < NUM_PAIRS; ++i) {
246	            uint64_t a_base = HAMMING_TABLE[i % HAMMING_TABLE_SIZE];
247	            uint64_t b_base = HAMMING_TABLE[(i + 1) % HAMMING_TABLE_SIZE];
248	
249	            uint64_t a[NUM_WORDS], b[NUM_WORDS];
250	            fill_operand(a, a_base);
251	            fill_operand(b, b_base);
252	
253	            memcpy(&data->a_words[i * NUM_WORDS], a, NUM_WORDS * sizeof(uint64_t));
254	            memcpy(&data->b_words[i * NUM_WORDS], b, NUM_WORDS * sizeof(uint64_t));
255	
256	            // Golden: 256-bit add (with carry-out).
257	            uint64_t sum[NUM_WORDS + 1];
258	            software_add_words(a, b, sum);
259	            memcpy(&data->golden_add[i * (NUM_WORDS + 1)], sum,
260	                   (NUM_WORDS + 1) * sizeof(uint64_t));
261	
262	            // Golden: full 64x64->128 multiply low word (UMULL low + UMULH high).
263	            // Keeping BOTH halves exercises the full multiplier partial-product
264	            // network — the high 64 bits are non-trivial (e.g. 0xFF..*0xFF.. ->
265	            // hi=0xFF..FE) and are a timing-critical path the low-only check
266	            // missed entirely.
267	            unsigned __int128 prod = (unsigned __int128)a[0] * (unsigned __int128)b[0];
268	            data->golden_mul_lo[i] = (uint64_t)prod;
269	            data->golden_mul_hi[i] = (uint64_t)(prod >> 64);
270	        }
271	
272	        test->data = data.release();
273	        return EXIT_SUCCESS;
274	    } catch (const std::exception &e) {
275	        log_skip(TestResourceIssueSkipCategory, "operand_space_arm init exception: %s", e.what());
276	        return EXIT_SKIP;
277	    }
278	}
279	
280	static int operand_space_arm_run(struct test *test, int cpu)
281	{
282	    (void)cpu;
283	    auto *td = static_cast<OperandSpaceData *>(test->data);
284	
285	    // Per-thread buffers (no cross-thread sharing).
286	    uint64_t a_words[NUM_WORDS];
287	    uint64_t b_words[NUM_WORDS];
288	    uint64_t hw_words[NUM_WORDS + 1];
289	
290	    mpz_t a_mpz, b_mpz, result_hw;
291	    mpz_init(a_mpz);
292	    mpz_init(b_mpz);
293	    mpz_init(result_hw);
294	
295	    do {
296	        bool all_passed = true;
297	
298	        for (size_t i = 0; i < td->num_pairs; ++i) {
299	            memcpy(a_words, &td->a_words[i * NUM_WORDS], NUM_WORDS * sizeof(uint64_t));
300	            memcpy(b_words, &td->b_words[i * NUM_WORDS], NUM_WORDS * sizeof(uint64_t));
301	
302	            // ---- Hardware path: 256-bit add via GMP mpz_add (lowers to ADCS).
303	            mpz_import(a_mpz, NUM_WORDS, -1, sizeof(uint64_t), 0, 0, a_words);
304	            mpz_import(b_mpz, NUM_WORDS, -1, sizeof(uint64_t), 0, 0, b_words);
305	            mpz_add(result_hw, a_mpz, b_mpz);
306	
307	            memset(hw_words, 0, (NUM_WORDS + 1) * sizeof(uint64_t));
308	            size_t count;
309	            mpz_export(hw_words, &count, -1, sizeof(uint64_t), 0, 0, result_hw);
310	            // (count <= NUM_WORDS+1; hw_words already zero-extended above.)
311	
312	            // ---- Golden compare (byte-exact, per word, including carry-out).
313	            const uint64_t *golden = &td->golden_add[i * (NUM_WORDS + 1)];
314	            bool data_ok = (memcmp(hw_words, golden, (NUM_WORDS + 1) * sizeof(uint64_t)) == 0);
315	
316	            // ---- Store-to-load-forwarding probe. Issue real str then ldr to
317	            // the same buffer (inline asm + "memory" clobber so the optimizer
318	            // cannot fuse/elide them); the reloads are satisfied by the store
319	            // buffer (store-to-load forwarding), a corruption-prone datapath the
320	            // previous software memcpy never touched. Golden = sum of the add
321	            // result words; a corrupted forward produces a different sum.
322	            uint64_t slf_buf[NUM_WORDS + 1];
323	            uint64_t slf_golden = 0;
324	            for (size_t w = 0; w < NUM_WORDS + 1; ++w)
325	                slf_golden += hw_words[w];
326	            uint64_t slf_got = slf_probe(hw_words, slf_buf, NUM_WORDS + 1);
327	            bool consistent = (slf_got == slf_golden);
328	
329	            // ---- Hardware path: full 64x64->128 multiply via mpz_mul on the
330	            // low limbs. mpz_mul of two 1-limb values exercises the 64x64
331	            // multiplier; we export BOTH 64-bit halves and check each against
332	            // the golden — the high half (UMULH) is a timing-critical path
333	            // the low-only check missed entirely.
334	            mpz_t a_lo, b_lo, mul_full;
335	            mpz_init(a_lo); mpz_init(b_lo); mpz_init(mul_full);
336	            mpz_import(a_lo, 1, -1, sizeof(uint64_t), 0, 0, &a_words[0]);
337	            mpz_import(b_lo, 1, -1, sizeof(uint64_t), 0, 0, &b_words[0]);
338	            mpz_mul(mul_full, a_lo, b_lo);
339	            // 128-bit export into two little-endian limbs.
340	            uint64_t hw_mul[2] = {0, 0};
341	            size_t mcount;
342	            mpz_export(hw_mul, &mcount, -1, sizeof(uint64_t), 0, 0, mul_full);
343	            bool mul_lo_ok = (hw_mul[0] == td->golden_mul_lo[i]);
344	            bool mul_hi_ok = (hw_mul[1] == td->golden_mul_hi[i]);
345	            bool mul_ok = (mul_lo_ok && mul_hi_ok);
346	            mpz_clear(a_lo); mpz_clear(b_lo); mpz_clear(mul_full);
347	
348	            if (!(data_ok && consistent && mul_ok)) {
349	                all_passed = false;
350	                // One-shot diagnostic log (NOT per-iteration flooding — avoids
351	                // the timing-perturbation hazard seen in adcx_arm.cpp:186).
352	                log_warning("operand_space_arm: mismatch at pair %zu "
353	                            "(add_ok=%d slf_ok=%d mul_lo_ok=%d mul_hi_ok=%d): "
354	                            "a0=0x%016" PRIx64 " b0=0x%016" PRIx64 " "
355	                            "hw_add_hi=0x%016" PRIx64 " golden_add_hi=0x%016" PRIx64 " "
356	                            "hw_mul_lo=0x%016" PRIx64 " golden_mul_lo=0x%016" PRIx64 " "
357	                            "hw_mul_hi=0x%016" PRIx64 " golden_mul_hi=0x%016" PRIx64,
358	                            i, data_ok, consistent, mul_lo_ok, mul_hi_ok,
359	                            a_words[0], b_words[0],
360	                            hw_words[NUM_WORDS], golden[NUM_WORDS],
361	                            hw_mul[0], td->golden_mul_lo[i],
362	                            hw_mul[1], td->golden_mul_hi[i]);
363	            }
364	        }
365	
366	        if (!all_passed) {
367	            mpz_clear(a_mpz); mpz_clear(b_mpz); mpz_clear(result_hw);
368	            report_fail_msg("operand_space_arm: high-Hamming operand SDC detected");
369	            return EXIT_FAILURE;
370	        }
371	
372	    } while (test_time_condition(test));
373	
374	    mpz_clear(a_mpz);
375	    mpz_clear(b_mpz);
376	    mpz_clear(result_hw);
377	    return EXIT_SUCCESS;
378	}
379	
380	static int operand_space_arm_finish(struct test *test)
381	{
382	    delete static_cast<OperandSpaceData *>(test->data);
383	    return EXIT_SUCCESS;
384	}
385	
386	DECLARE_TEST(operand_space_arm,
387	             "Operand-space SDC stress: high-Hamming-distance operands forcing "
388	             "maximum adder/carry-chain/multiplier gate toggling (ARM64 ADCS/UMULL via GMP)")
389	    .groups = DECLARE_TEST_GROUPS(&group_math),
390	    .test_init = operand_space_arm_init,
391	    .test_run = operand_space_arm_run,
392	    .test_cleanup = operand_space_arm_finish,
393	    .fracture_loop_count = 4,
394	    .quality_level = TEST_QUALITY_PROD
395	END_DECLARE_TEST
