1	/**
2	 * @file
3	 *
4	 * @copyright
5	 * Copyright 2022 Intel Corporation.
6	 * SPDX-License-Identifier: Apache-2.0
7	 *
8	 * @test @b crt_builtins
9	 * @parblock
10	 * Stress the integer ALU by repeatedly executing the LLVM
11	 * compiler-rt soft-float builtins (__addsf3 / __mulsf3 / __divsf3)
12	 * which implement IEEE-754 single-precision arithmetic purely in
13	 * integer operations.  A table of random float operands is generated
14	 * at init and the hardware-computed result (using the native FPU) is
15	 * stored as the golden.  During the run the same operations are
16	 * re-evaluated through the compiler-rt integer implementations and
17	 * compared bit-exactly against the golden.  Because the soft-float
18	 * routines touch many integer ALU resources (shifts, adds, compares)
19	 * while producing a deterministic result, any mismatch indicates a
20	 * silent corruption in the integer execution path.
21	 * @endparblock
22	 */
23	
24	#include <sandstone.h>
25	
26	/* compiler-rt soft-float builtins: IEEE-754 implemented in integer ALU.
27	 * Declared extern "C" so the linker binds to libclang_rt.builtins. */
28	extern "C" {
29	    float __addsf3(float, float);
30	    float __subsf3(float, float);
31	    float __mulsf3(float, float);
32	    float __divsf3(float, float);
33	}
34	
35	#define CRT_COUNT (1 << 12)   /* 4096 operand pairs */
36	
37	namespace {
38	struct crt_data {
39	    float *a;
40	    float *b;
41	    float *golden_add;
42	    float *golden_mul;
43	    float *golden_div;
44	};
45	}
46	
47	#define CAST(_x) static_cast<struct crt_data *>(_x)
48	
49	static int crt_builtins_init(struct test *test)
50	{
51	    crt_data *data = new crt_data;
52	    data->a          = (float *)aligned_alloc_safe(64, CRT_COUNT * sizeof(float));
53	    data->b          = (float *)aligned_alloc_safe(64, CRT_COUNT * sizeof(float));
54	    data->golden_add = (float *)aligned_alloc_safe(64, CRT_COUNT * sizeof(float));
55	    data->golden_mul = (float *)aligned_alloc_safe(64, CRT_COUNT * sizeof(float));
56	    data->golden_div = (float *)aligned_alloc_safe(64, CRT_COUNT * sizeof(float));
57	
58	    for (size_t i = 0; i < CRT_COUNT; ++i) {
59	        /* avoid divisors near zero: pick b from a safe non-zero range */
60	        data->a[i] = (float)((int32_t)random32()) / (float)(1u << 24);
61	        float bv;
62	        do { bv = (float)((int32_t)random32()) / (float)(1u << 24); }
63	        while (bv > -0.5f && bv < 0.5f);
64	        data->b[i] = bv;
65	        /* golden computed once on the hardware FPU */
66	        data->golden_add[i] = data->a[i] + data->b[i];
67	        data->golden_mul[i] = data->a[i] * data->b[i];
68	        data->golden_div[i] = data->a[i] / data->b[i];
69	    }
70	    test->data = data;
71	    return EXIT_SUCCESS;
72	}
73	
74	static int crt_builtins_run(struct test *test, int cpu)
75	{
76	    auto data = CAST(test->data);
77	    do {
78	        for (size_t i = 0; i < CRT_COUNT; ++i) {
79	            float add = __addsf3(data->a[i], data->b[i]);
80	            float mul = __mulsf3(data->a[i], data->b[i]);
81	            float div = __divsf3(data->a[i], data->b[i]);
82	            if (memcmp(&add, &data->golden_add[i], sizeof(float)) != 0) {
83	                report_fail_msg("crt __addsf3 mismatch at %zu: 0x%08x vs 0x%08x",
84	                                i, *(unsigned int *)&add,
85	                                *(unsigned int *)&data->golden_add[i]);
86	            }
87	            if (memcmp(&mul, &data->golden_mul[i], sizeof(float)) != 0) {
88	                report_fail_msg("crt __mulsf3 mismatch at %zu: 0x%08x vs 0x%08x",
89	                                i, *(unsigned int *)&mul,
90	                                *(unsigned int *)&data->golden_mul[i]);
91	            }
92	            if (memcmp(&div, &data->golden_div[i], sizeof(float)) != 0) {
93	                report_fail_msg("crt __divsf3 mismatch at %zu: 0x%08x vs 0x%08x",
94	                                i, *(unsigned int *)&div,
95	                                *(unsigned int *)&data->golden_div[i]);
96	            }
97	        }
98	    } while (test_time_condition(test));
99	    return EXIT_SUCCESS;
100	}
101	
102	static int crt_builtins_cleanup(struct test *test)
103	{
104	    crt_data *data = CAST(test->data);
105	    free(data->a);
106	    free(data->b);
107	    free(data->golden_add);
108	    free(data->golden_mul);
109	    free(data->golden_div);
110	    delete data;
111	    return EXIT_SUCCESS;
112	}
113	
114	DECLARE_TEST(crt_builtins, "compiler-rt soft-float builtins (__addsf3/__mulsf3/__divsf3) vs golden")
115	  .groups = DECLARE_TEST_GROUPS(&group_math),
116	  .test_init = crt_builtins_init,
117	  .test_run = crt_builtins_run,
118	  .test_cleanup = crt_builtins_cleanup,
119	  .quality_level = TEST_QUALITY_PROD,
120	END_DECLARE_TEST
121

